import{_ as e,o as s,c as n,ag as t}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"Clean URLs","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/configurations/clean-urls.md","filePath":"installation-guide/configurations/clean-urls.md","lastUpdated":1786379412000}'),i={name:"installation-guide/configurations/clean-urls.md"};function p(l,a,o,c,r,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="clean-urls" tabindex="-1">Clean URLs <a class="header-anchor" href="#clean-urls" aria-label="Permalink to &quot;Clean URLs&quot;">​</a></h1><p>Clean URLs are user-friendly addresses that omit unnecessary elements such as <code>index.php</code> from the path. The steps below configure <strong>Apache</strong>. IIS URL Rewrite and NGINX are not fully documented here — see <a href="./../platform-windows.html">Installation (Windows)</a> and <a href="./../platform-linux.html">Installation (Linux)</a>.</p><h2 id="update-config-php" tabindex="-1">Update config.php <a class="header-anchor" href="#update-config-php" aria-label="Permalink to &quot;Update config.php&quot;">​</a></h2><p>Open <code>application/config/config.php</code> and update the setting:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$config[&#39;index_page&#39;] = &#39;&#39;;</span></span></code></pre></div><h2 id="enable-apache-mod-rewrite" tabindex="-1">Enable Apache mod_rewrite <a class="header-anchor" href="#enable-apache-mod-rewrite" aria-label="Permalink to &quot;Enable Apache mod_rewrite&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo a2enmod rewrite</span></span>
<span class="line"><span>$ sudo service apache2 restart</span></span></code></pre></div><h2 id="update-apache-configuration" tabindex="-1">Update Apache Configuration <a class="header-anchor" href="#update-apache-configuration" aria-label="Permalink to &quot;Update Apache Configuration&quot;">​</a></h2><p>Allow .htaccess overrides by editing Apache’s config:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;Directory &quot;/var/www/html/nada&quot;&gt;</span></span>
<span class="line"><span>    AllowOverride All</span></span>
<span class="line"><span>&lt;/Directory&gt;</span></span></code></pre></div><h2 id="create-or-edit-htaccess" tabindex="-1">Create or Edit .htaccess <a class="header-anchor" href="#create-or-edit-htaccess" aria-label="Permalink to &quot;Create or Edit .htaccess&quot;">​</a></h2><p>In your NADA root folder (/nada/), create/edit <code>.htaccess</code> file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;IfModule mod_rewrite.c&gt;</span></span>
<span class="line"><span>    RewriteEngine On</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    # enable line below, if using a sub-folder </span></span>
<span class="line"><span>    #RewriteBase /myproject/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    RewriteCond %{REQUEST_FILENAME} !-f</span></span>
<span class="line"><span>    RewriteCond %{REQUEST_FILENAME} !-d</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    RewriteRule ^(.*)$ index.php/$1 [L]</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Note: For hosting NADA in a subfolder e.g. <code>https://example.com/nada/</code>, uncomment the line for RewriteBase and make sure to use the correct subfolder name.</p></div>`,14)])])}const g=e(i,[["render",p]]);export{u as __pageData,g as default};
